namespace delete_inactive_users {

struct User {
  PrimaryKey<int> user_id;
  std::string username;
  std::optional<DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  // Begin transaction
  auto transaction_result = sqlgen::begin_transaction(conn_result);

  // Delete users who have not logged in since 2025-01-01
  auto delete_result = transaction_result.and_then([](auto transaction) {
    return (sqlgen::delete_from<User>(transaction) | 
            sqlgen::where("last_login"_c < DateTime(2025, 1, 1)));
  });

  // Commit the transaction and return the operation result
  auto commit_result = delete_result.and_then(sqlgen::commit);

  // Return 0 for success, 1 for failure
  return commit_result.is_ok() ? 0 : 1;
}

} // namespace delete_inactive_users
```

