    rfl::Field<"Remark", rfl::Box<std::string>> remark;
  };

  struct Course {
    rfl::Field<"CID", int> cid;
    rfl::Field<"CName", std::string> cname;
    rfl::Field<"Term", rfl::Box<int>> term = rfl::default_value(1);
    rfl::Field<"CTime", rfl::Box<int>> ctime;
    rfl::Field<"Credit", float> credit = rfl::default_value(0.0f);
  };

  struct Score {
    rfl::Field<"SNo", std::string> sno;
    rfl::Field<"CID", int> cid;
    rfl::Field<"Score", rfl::Box<float>> score;
  };

  void design_eas_database() {
    // Connect to SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

    if (!conn_result) {
      // Handle connection error
