    // Create Course table  
    auto course_result = sqlgen::create_table<Course>(conn, true);
    if (!course_result) {
      // Handle table creation error
      return;
    }

    // Create Score table with composite primary key and foreign keys using raw SQL
    // since the sqlgen library may not support complex constraints through structs
    std::string score_table_sql = R"(
        CREATE TABLE IF NOT EXISTS Score (
            SNo VARCHAR(10) NOT NULL,
            CID INT NOT NULL,
            Score FLOAT NULL,
            PRIMARY KEY (SNo, CID),
            FOREIGN KEY (SNo) REFERENCES Student(SNo),
            FOREIGN KEY (CID) REFERENCES Course(CID)
