namespace query_active_users_posts {

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  PrimaryKey<int> post_id;
  int user_id;
  DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  PrimaryKey<int> user_id;
  std::string username;
};

std::vector<ActiveUser> query_active_users_posts() {
    using namespace sqlgen::literals;

    // 1. Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

    // 2. Create User and Post tables (if not exists)
    (conn | create_table<User>.if_not_exists() | create_table<Post>.if_not_exists()).value();

    // 3. Query for active users who posted between 2025-12-01 and 2025-12-31
    auto results = (conn 
        | select_from<User, "u">("u.user_id"_c, "u.username"_c)
        | inner_join<Post, "p">("u.user_id"_c == "p.user_id"_c)
        | where("p.created_at"_c >= "2025-12-01" && "p.created_at"_c <= "2025-12-31")
        | to<std::vector<ActiveUser>>()
    ).value();

    return results;
}

}  // namespace query_active_users_posts
```

