  ForeignKey<int, Customer, "customer_id"> customer_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  PrimaryKey<int> item_id;
  ForeignKey<int, Order, "order_id"> order_id;
  ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = conn_result.value();

  // 2. Create tables if they don't exist
  auto create_customer = conn | sqlgen::create_table<Customer>(true);
  if (!create_customer) {
    throw std::runtime_error("Failed to create Customer table: " + create_customer.error().what());
  }

  auto create_product = create_customer.value() | sqlgen::create_table<Product>(true);
  if (!create_product) {
    throw std::runtime_error("Failed to create Product table: " + create_product.error().what());
  }

  auto create_order = create_product.value() | sqlgen::create_table<Order>(true);
  if (!create_order) {
    throw std::runtime_error("Failed to create Order table: " + create_order.error().what());
  }

  auto create_order_item = create_order.value() | sqlgen::create_table<OrderItem>(true);
  if (!create_order_item) {
    throw std::runtime_error("Failed to create OrderItem table: " + create_order_item.error().what());
  }

  // 3. Query the database to retrieve all products purchased by a specific customer
  // Using the reference SQL as a guide:
  // SELECT p.name, o.order_date, oi.quantity
  // FROM Customer c
  // JOIN "Order" o ON c.customer_id = o.customer_id
  // JOIN OrderItem oi ON o.order_id = oi.order_id
  // JOIN Product p ON oi.product_id = p.product_id
  // WHERE c.customer_id = ?
  // ORDER BY o.order_date DESC;

  auto query = select_from<Customer>("c"_t1, "name"_c, "order_date"_c, "quantity"_c)
    | sqlgen::inner_join<Order>("o"_t2, "c.customer_id"_c == "o.customer_id"_c)
    | sqlgen::inner_join<OrderItem>("oi"_t3, "o.order_id"_c == "oi.order_id"_c)
    | sqlgen::inner_join<Product>("p"_t4, "oi.product_id"_c == "p.product_id"_c)
    | sqlgen::where("c.customer_id"_c == customer_id)
    | sqlgen::order_by("o.order_date"_c.desc());

  // 4. Read and return the results as a vector of PurchaseHistory
  auto result = query(create_order_item.value());
  if (!result) {
    throw std::runtime_error("Query failed: " + result.error().what());
  }

  // Convert the result to vector of PurchaseHistory
  std::vector<PurchaseHistory> purchase_history;
  for (auto&& row : result.value()) {
    purchase_history.push_back(PurchaseHistory{
      .product_name = std::move(row.template get<"name">()),
      .order_date = std::move(row.template get<"order_date">()),
      .quantity = row.template get<"quantity">()
    });
  }

  return purchase_history;
}

}  // namespace query_customer_purchase_history

