namespace query_employee_hierarchy {

struct Employee {
  PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

std::vector<EmployeeManager> query_employee_hierarchy() {
    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

    if (!conn_result) {
        // Return empty vector if connection fails
        return {};
    }

    auto conn = *conn_result;

    // Perform self-join using LEFT JOIN to handle employees without managers
    // e1 represents employees, e2 represents managers
    auto result = sqlgen::select_from<Employee, "e1">(
        "e1.name"_c.as<"employee">(),
        "e2.name"_c.as<"manager">()
    )
    | sqlgen::left_join<Employee, "e2">("e1.manager_id"_c == "e2.emp_id"_c)
    | sqlgen::to<std::vector<EmployeeManager>>(conn);

    if (result) {
        return *result;
    } else {
        // Return empty vector if query fails
        return {};
    }
}

}  // namespace query_employee_hierarchy
