    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, WhereType,
               GroupByType, OrderByType, LimitType, ToType>> {
  dynamic::SelectFrom::TableOrQueryType operator()(const auto& _query) {
    using TableTupleType =
