using namespace sqlgen::literals;

namespace query_search_books_by_criteria {

struct Book {
  PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    // Connect to SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        // Return empty vector if connection fails
        return {};
    }

    auto conn = *conn_result;

    // Start with base SELECT query
    auto query = sqlgen::select_from<Book>("book_id"_c, "title"_c, "author"_c, "year"_c, "genre"_c, "price"_c);

    // Build WHERE conditions dynamically based on provided filters
    bool has_condition = false;
    auto condition = sqlgen::where(true); // Start with a dummy true condition

    if (filters.title_keyword.has_value()) {
        auto title_condition = "title"_c.like("%" + *filters.title_keyword + "%");
        if (!has_condition) {
            condition = sqlgen::where(title_condition);
            has_condition = true;
        } else {
            condition = sqlgen::where(condition.condition && title_condition);
        }
    }

    if (filters.min_year.has_value()) {
        auto year_condition = "year"_c >= *filters.min_year;
        if (!has_condition) {
            condition = sqlgen::where(year_condition);
            has_condition = true;
        } else {
            condition = sqlgen::where(condition.condition && year_condition);
        }
    }

    if (filters.genre.has_value()) {
        auto genre_condition = "genre"_c == *filters.genre;
        if (!has_condition) {
            condition = sqlgen::where(genre_condition);
            has_condition = true;
        } else {
            condition = sqlgen::where(condition.condition && genre_condition);
        }
    }

    if (filters.max_price.has_value()) {
        auto price_condition = "price"_c <= *filters.max_price;
        if (!has_condition) {
            condition = sqlgen::where(price_condition);
            has_condition = true;
        } else {
            condition = sqlgen::where(condition.condition && price_condition);
        }
    }

    // Apply the condition if any filter was provided
    if (has_condition) {
        query = query | condition;
    }

    // Execute the query
    auto result = query(conn);

    if (result) {
        return *result;
    } else {
        // Return empty vector if query fails
        return {};
    }
}

}  // namespace query_search_books_by_criteria
```

Key points about this implementation:

1. **Database Connection**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the SQLite database.

2. **Base Query**: Starts with `sqlgen::select_from<Book>` to select all columns from the Book table.

3. **Dynamic WHERE Clauses**: Builds conditions dynamically by checking which filters are provided:
   - Uses `LIKE` with wildcards for title keyword search
   - Uses `>=` for minimum year
   - Uses `==` for exact genre match
   - Uses `<=` for maximum price

4. **Condition Combination**: Combines multiple conditions with `&&` (AND) when multiple filters are provided.

5. **Error Handling**: Returns empty vector if database connection fails or query execution fails.

6. **Type Safety**: Uses the sqlgen library's type-safe column references like `"title"_c`, `"year"_c`, etc.

The function will construct SQL queries like:
- If all filters are provided: `SELECT * FROM Book WHERE title LIKE ? AND year >= ? AND genre = ? AND price <= ?`
- If only title and price filters are provided: `SELECT * FROM Book WHERE title LIKE ? AND price <= ?`
- If no filters are provided: `SELECT * FROM Book`

