```cpp
#pragma once

#include <vector>
#include <string>
#include <optional>

#include "sqlgen/sqlite/connect.hpp"
#include "sqlgen/update.hpp"
#include "sqlgen/where.hpp"
#include "sqlgen/commit.hpp"
#include "sqlgen/literals.hpp"

namespace soft_delete_records {

using namespace sqlgen::literals;

struct Document {
  PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    if (ids.empty()) {
        return true; // Nothing to delete
    }

    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return false;
    }

    // Use the connection to perform the soft delete update
    auto result = conn_result 
        | sqlgen::update<Document>(
            "is_deleted"_c.set(1),
            "deleted_at"_c.set("CURRENT_TIMESTAMP")
          )
        | sqlgen::where("doc_id"_c.in(ids))
        | sqlgen::commit();

    return result.has_value();
}

}  // namespace soft_delete_records
```

This implementation:

1. **Connects to the database** using `sqlgen::sqlite::connect("test_db.sqlite")`
2. **Uses the update functionality** from sqlgen to set:
   - `is_deleted` to 1
   - `deleted_at` to CURRENT_TIMESTAMP
3. **Applies the WHERE condition** using `doc_id.in(ids)` to target specific records
4. **Commits the transaction** and returns success/failure
5. **Handles empty ID lists** gracefully by returning true (nothing to do)

The sqlgen library's fluent interface allows us to chain operations together in a readable way, and the `in()` method handles the SQL IN clause automatically for the vector of IDs.

