        using DurationType = std::remove_cvref_t<T>;
        return Operation<Operator::date_plus_duration, Operation,
                         rfl::Tuple<DurationType>>{
            .operand1 = _op1, .operand2 = rfl::Tuple<DurationType>(_op2)};
