  }

  template <class T>
  friend auto operator/(const Operation& _op1, const T& _op2) noexcept {
    using OtherType = typename transpilation::ToTranspilationType<
        std::remove_cvref_t<T>>::Type;

    return Operation<Operator::divides, Operation, OtherType>{
