#pragma once

#include <chrono>
#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/update.hpp>
#include <sqlgen/where.hpp>
#include <sqlgen/col.hpp>

namespace update_order_status {

struct Order {
  PrimaryKey<int> order_id;
  std::string status;
  DateTime order_date;
  double total_amount;
};

int update_order_status() {
   // Connect to SQLite database
   auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
   if (!conn_result) {
       return 0; // Return 0 if connection fails
   }
   auto conn = conn_result.value();

   int total_affected = 0;

   // Update pending orders older than 7 days to 'expired'
   auto update_expired = sqlgen::update<Order>(
       sqlgen::col<"status">.set("expired"),
       sqlgen::where(
           (sqlgen::col<"status"> == "pending") && 
           (sqlgen::col<"order_date"> < (std::chrono::system_clock::now() - std::chrono::days(7)))
       )
   );

   auto result1 = update_expired(conn);
   if (result1) {
       // Get number of rows affected for expired orders
       total_affected += result1.value()->changes();
   }

   // Update shipped orders to 'delivered' (simulating delivery confirmation)
   auto update_delivered = sqlgen::update<Order>(
       sqlgen::col<"status">.set("delivered"),
       sqlgen::where(sqlgen::col<"status"> == "shipped")
   );

   auto result2 = update_delivered(conn);
   if (result2) {
       // Get number of rows affected for delivered orders
       total_affected += result2.value()->changes();
   }

   return total_affected;
}

} // namespace update_order_status
```

