#include <string>

#include "sqlgen/sqlite/connect.hpp"
#include "sqlgen/write.hpp"
#include "sqlgen/read.hpp"
#include "sqlgen/literals.hpp"
#include "sqlgen/operations.hpp"
#include "sqlgen/as.hpp"

namespace analyze_temporal_data {

struct Event {
  PrimaryKey<int> event_id;
  std::string event_name;
  Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  using namespace sqlgen::literals;
  using namespace sqlgen::operations;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database");
  }
  auto conn = conn_result.value();

  // Write events to the database
  auto write_result = sqlgen::write(conn, events);
  if (!write_result) {
    throw std::runtime_error("Failed to write events to database");
  }

  // Build the temporal analysis query using SQLGen operations
  auto query = select(
    "event_id"_c,
    "event_name"_c,
    day("start_time"_c) | sqlgen::as<"start_day">,
    month("start_time"_c) | sqlgen::as<"start_month">,
    year("start_time"_c) | sqlgen::as<"start_year">,
    hour("start_time"_c) | sqlgen::as<"start_hour">,
    minute("start_time"_c) | sqlgen::as<"start_minute">,
    second("start_time"_c) | sqlgen::as<"start_second">,
    weekday("start_time"_c) | sqlgen::as<"start_weekday">,
    unixepoch("start_time"_c) | sqlgen::as<"start_epoch">,
    days_between("start_time"_c, "end_time"_c) | sqlgen::as<"duration_days">
  ).from<Event>().where("end_time"_c.is_not_null());

  // Execute the query and return results
  auto analysis_result = conn->read<std::vector<TemporalAnalysis>>(query);
  if (!analysis_result) {
    throw std::runtime_error("Failed to read temporal analysis results");
  }

  return analysis_result.value();
}

}  // namespace analyze_temporal_data
```

This implementation:

1. **Connects to the SQLite database** using `sqlgen::sqlite::connect("test_db.sqlite")`
2. **Writes events to the database** using `sqlgen::write(conn, events)`
3. **Builds the temporal analysis query** using SQLGen's fluent interface:
   - Uses date/time extraction functions: `day()`, `month()`, `year()`, `hour()`, `minute()`, `second()`
   - Uses `weekday()` for weekday information
   - Uses `unixepoch()` to convert to Unix timestamp
   - Uses `days_between()` to calculate duration
   - Uses `as<>` for column aliases
4. **Filters events** with `where("end_time"_c.is_not_null())` to only include events with end times
5. **Executes the query** and returns the results as `std::vector<TemporalAnalysis>`

The function handles error cases by throwing exceptions if any database operation fails, ensuring robust error handling while maintaining the clean SQLGen API style.

