 * It inserts or replaces the given inventory items in the Inventory table.
 */
bool upsert_inventory_items(const std::vector<Inventory>& items) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Perform upsert operation using write API
  // The write function with PrimaryKey fields automatically handles insert-or-replace behavior
  auto write_result = sqlgen::write(conn_result, items);
  if (!write_result) {
    return false;
  }

  // Read back items to verify the upsert operation
  auto read_result = sqlgen::read<std::vector<Inventory>>(write_result);
  if (!read_result) {
    return false;
  }

  // Verify that we can read back the items successfully
  // This confirms the upsert operation was successful
  auto verified_items = read_result.value();

  // Additional verification: check if all upserted items are present
  // This ensures the primary key constraint and upsert behavior worked correctly
  for (const auto& item : items) {
    bool found = false;
    for (const auto& verified_item : verified_items) {
      if (verified_item.item_id == item.item_id) {
        found = true;
        // Optional: verify other fields match
        if (verified_item.name != item.name || verified_item.quantity != item.quantity) {
          return false; // Data mismatch indicates upsert didn't work correctly
        }
        break;
