  }

  template <class T>
  friend auto operator>(const Operation& _o, const T& _t) {
    return make_condition(
        conditions::greater_than(_o, to_transpilation_type(_t)));
  }

  template <class T>
  friend auto operator>=(const Operation& _o, const T& _t) {
    return make_condition(
