```cpp
#pragma once

#include <rfl.hpp>
#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/select_from.hpp>
#include <sqlgen/col.hpp>
#include <sqlgen/literals.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = conn_result.value();

  // Create temporary table for OrderItem data
  conn->execute(R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS TempOrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )").value();

  // Clear any existing data
  conn->execute("DELETE FROM TempOrderItem").value();

  // Insert all items into temporary table
  for (const auto& item : items) {
    conn->execute(
      "INSERT INTO TempOrderItem (item_id, order_id, product_id, unit_price, quantity, discount_rate, tax_rate) VALUES (?, ?, ?, ?, ?, ?, ?)",
      item.item_id, item.order_id, item.product_id, item.unit_price, item.quantity, 
      item.discount_rate.value_or(0.0), item.tax_rate.value_or(0.0)
    ).value();
  }

  // Define the query using sqlgen's ORM capabilities
  auto query = sqlgen::select_from<rfl::Rename<"TempOrderItem", OrderItem>>(
    "item_id"_c,
    "order_id"_c, 
    "product_id"_c,
    "unit_price"_c,
    "quantity"_c,
    "discount_rate"_c,
    "tax_rate"_c,
    ("unit_price"_c * "quantity"_c).as("gross_total"),
    ("unit_price"_c * "quantity"_c * (1 - "discount_rate"_c / 100.0)).as("discounted_total"),
    ("unit_price"_c * "quantity"_c * (1 - "discount_rate"_c / 100.0) * (1 + "tax_rate"_c / 100.0)).as("final_total"),
    (("unit_price"_c * "quantity"_c) / "quantity"_c).as("unit_cost"),
    ("quantity"_c % 10).as("quantity_group"),
    ("unit_price"_c * 0.3).as("estimated_profit")
  ) | sqlgen::to<std::vector<OrderMetrics>>;

  // Execute query and return results
  auto result = query(conn);
  if (!result) {
    throw std::runtime_error("Failed to execute query: " + result.error().what());
  }

  return result.value();
}

}  // namespace calculate_order_metrics
```

This implementation:

1. **Connects to SQLite database**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the specified database.

2. **Creates temporary table**: Creates a temporary table `TempOrderItem` with the same structure as the `OrderItem` struct.

3. **Inserts data**: Inserts all provided `OrderItem` objects into the temporary table, handling optional fields with `value_or(0.0)`.

4. **Performs arithmetic operations**: Uses `sqlgen`'s column operations to implement the required calculations:
   - **Multiplication**: `"unit_price"_c * "quantity"_c` for gross total
   - **Division and percentage operations**: For discount and tax calculations
   - **Modulo**: `"quantity"_c % 10` for quantity groups
   - **Mixed operations**: Combining multiplication, division, addition, and subtraction

5. **Returns comprehensive metrics**: The query returns all calculated fields mapped to the `OrderMetrics` struct.

6. **Error handling**: Properly handles connection and query execution errors by throwing exceptions with descriptive messages.

The solution leverages the `sqlgen` library's type-safe ORM features while performing all the required arithmetic operations as specified in the SQL reference query.

