  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    // Handle connection error - return empty vector or throw exception
    return {};
  }

  // Perform the join operation
  auto result = sqlgen::select_from<Order>("o"_t1.order_id, 
                                          "c"_t2.name | sqlgen::as<"customer_name">, 
                                          "p"_t3.amount)
              | sqlgen::inner_join<Customer, "c">("o"_t1.customer_id == "c"_t2.customer_id)
              | sqlgen::inner_join<Payment, "p">("o"_t1.order_id == "p"_t3.order_id)
              | sqlgen::order_by("p"_t3.amount.desc())
              | sqlgen::to<std::vector<Consolidated>>();

  // Execute the query and return results
  auto query_result = result(conn.value());
  if (query_result) {
