```cpp
#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/update.hpp>
#include <sqlgen/read.hpp>
#include <sqlgen/operations.hpp>
#include <sqlgen/literals.hpp>

namespace replace_text_in_notes {

struct Note {
  PrimaryKey<int> note_id;
  std::string content;
};

struct UpdatedNote {
  PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (conn_result.is_err()) {
    throw std::runtime_error("Failed to connect to database");
  }
  auto conn = conn_result.value();

  // Define columns using literals
  const auto note_id = "note_id"_c;
  const auto content = "content"_c;

  // Update the Notes table: replace "foo" with "bar" in content column
  auto update_result = sqlgen::update<Note>(
    content.set(sqlgen::replace(content, "foo", "bar"))
  )(conn);

  if (update_result.is_err()) {
    throw std::runtime_error("Failed to update notes");
  }

  // Read the updated notes and return them
  auto read_result = sqlgen::read<std::vector<UpdatedNote>>()(conn);
  if (read_result.is_err()) {
    throw std::runtime_error("Failed to read updated notes");
  }

  return read_result.value();
}

}  // namespace replace_text_in_notes
