      check_aggregations<
          TablesType, rfl::Tuple<typename OrderByWrapper<ColTypes>::ColType...>,
          GroupByType>(),
      "The columns in the ORDER BY clause have not been properly "
      "aggregated. Please refer to the stack trace for details.");

