#pragma once

#include <vector>
#include <iostream>
#include "sqlgen/sqlite/connect.hpp"
#include "sqlgen/create_table.hpp"
#include "sqlgen/insert.hpp"
#include "sqlgen/delete_from.hpp"
#include "sqlgen/where.hpp"
#include "sqlgen/field.hpp"
#include "sqlgen/select.hpp"
#include "sqlgen/all.hpp"

namespace cascade_delete_demo {

struct Parent {
  PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  PrimaryKey<int> child_id;
  ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  try {
    // 1. Connect to SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
      std::cerr << "Failed to connect to database" << std::endl;
      return false;
    }
    auto conn = conn_result.value();

    // Enable foreign key constraints (important for cascade delete to work in SQLite)
    auto pragma_result = conn->execute("PRAGMA foreign_keys = ON;");
    if (!pragma_result) {
      std::cerr << "Failed to enable foreign keys" << std::endl;
      return false;
    }

    // 2. Create Parent and Child tables
    auto create_parent_result = conn | sqlgen::create_table<Parent>;
    if (!create_parent_result) {
      std::cerr << "Failed to create Parent table" << std::endl;
      return false;
    }

    auto create_child_result = create_parent_result.value() | sqlgen::create_table<Child>;
    if (!create_child_result) {
      std::cerr << "Failed to create Child table" << std::endl;
      return false;
    }

    // 3. Insert parent and child records with the same parent_id
    Parent parent1{1, "Parent One"};
    Parent parent2{2, "Parent Two"};

    Child child1{1, 1, "Child of Parent One - 1"};
    Child child2{2, 1, "Child of Parent One - 2"};
    Child child3{3, 2, "Child of Parent Two"};

    // Insert parents
    auto insert_parent_result = create_child_result.value() | sqlgen::insert(std::vector{parent1, parent2});
    if (!insert_parent_result) {
      std::cerr << "Failed to insert parent records" << std::endl;
      return false;
    }

    // Insert children
    auto insert_child_result = insert_parent_result.value() | sqlgen::insert(std::vector{child1, child2, child3});
    if (!insert_child_result) {
      std::cerr << "Failed to insert child records" << std::endl;
      return false;
    }

    // 4. Verify initial state - count children for parent_id = 1
    auto count_before_result = insert_child_result.value() | 
                              sqlgen::select<Child> | 
                              sqlgen::where(sqlgen::field(&Child::parent_id) == 1) |
                              sqlgen::count;

    if (!count_before_result) {
      std::cerr << "Failed to count child records before deletion" << std::endl;
      return false;
    }

    int child_count_before = count_before_result.value();
    std::cout << "Children for parent_id=1 before deletion: " << child_count_before << std::endl;

    // 5. Delete parent with parent_id = 1 (should cascade delete children)
    auto delete_parent_result = insert_child_result.value() | 
                               sqlgen::delete_from<Parent> | 
                               sqlgen::where(sqlgen::field(&Parent::parent_id) == 1);

    if (!delete_parent_result) {
      std::cerr << "Failed to delete parent record" << std::endl;
      return false;
    }

    // 6. Verify cascade deletion - count children for parent_id = 1 after deletion
    auto count_after_result = delete_parent_result.value() | 
                             sqlgen::select<Child> | 
                             sqlgen::where(sqlgen::field(&Child::parent_id) == 1) |
                             sqlgen::count;

    if (!count_after_result) {
      std::cerr << "Failed to count child records after deletion" << std::endl;
      return false;
    }

    int child_count_after = count_after_result.value();
    std::cout << "Children for parent_id=1 after deletion: " << child_count_after << std::endl;

    // 7. Verify that parent_id=2 children still exist
    auto count_parent2_result = delete_parent_result.value() | 
                               sqlgen::select<Child> | 
                               sqlgen::where(sqlgen::field(&Child::parent_id) == 2) |
                               sqlgen::count;

    if (!count_parent2_result) {
      std::cerr << "Failed to count child records for parent_id=2" << std::endl;
      return false;
    }

    int parent2_child_count = count_parent2_result.value();
    std::cout << "Children for parent_id=2: " << parent2_child_count << std::endl;

    // 8. Return verification result
    bool cascade_worked = (child_count_before > 0) && (child_count_after == 0);
    bool other_parent_unaffected = (parent2_child_count == 1); // We inserted 1 child for parent_id=2

    std::cout << "Cascade delete worked: " << (cascade_worked ? "YES" : "NO") << std::endl;
    std::cout << "Other parent unaffected: " << (other_parent_unaffected ? "YES" : "NO") << std::endl;

    return cascade_worked && other_parent_unaffected;

  } catch (const std::exception& e) {
    std::cerr << "Exception in cascade_delete_demo: " << e.what() << std::endl;
    return false;
  }
}

}  // namespace cascade_delete_demo
```

