```cpp
#pragma once

#include <vector>
#include <optional>
#include <string>

#include "sqlgen/sqlite/connect.hpp"
#include "sqlgen/read.hpp"
#include "sqlgen/where.hpp"
#include "sqlgen/literals.hpp"

namespace column_is_null_checks {

struct Profile {
  PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_result) {
    // Return empty vector if connection fails
    return {};
  }

  auto conn = conn_result.value();

  // Define columns using literals
  auto bio_col = "bio"_c;
  auto avatar_url_col = "avatar_url"_c;

  // Filter rows where bio is NULL (missing) OR avatar_url is NOT NULL (present)
  auto condition = bio_col.is_null() || avatar_url_col.is_not_null();

  // Read profiles with the filter condition
  auto profiles_result = conn | sqlgen::read<std::vector<Profile>> | sqlgen::where(condition);

  if (!profiles_result) {
    // Return empty vector if query fails
    return {};
  }

  auto profiles = profiles_result.value();

  // Convert Profile objects to Result objects
  std::vector<Result> results;
  results.reserve(profiles.size());

  for (const auto& profile : profiles) {
    results.push_back(Result{
      .profile_id = profile.profile_id,
      .display_name = profile.display_name
    });
  }

  return results;
}

}  // namespace column_is_null_checks
