1. Read all books ordered by pages in descending order
2. Use `select_from` with `to<std::vector<T>>`
3. Return a vector of book records

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/select_from.hpp>
#include <sqlgen/to.hpp>
#include <sqlgen/literals.hpp>
#include <sqlgen/order_by.hpp>
#include <stdexcept>

namespace select_from_read_to_vector {

struct Book {
  PrimaryKey<int> book_id;
  std::string title;
  int pages;
};

/**
 * description: select_from_read_to_vector.
 * This function demonstrates how to read data from a table using sqlgen read API and store it in a vector.
 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  // Connect to SQLite database (using in-memory database as default)
  auto conn_result = sqlgen::sqlite::connect();
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = *conn_result;

  // Use select_from to query all books, order by pages in descending order, and convert to vector
  auto result = sqlgen::select_from<Book>("book_id"_c, "title"_c, "pages"_c)
                | sqlgen::order_by("pages"_c.desc())
                | sqlgen::to<std::vector<Book>>()
                (conn);

  if (!result) {
    throw std::runtime_error("Failed to execute query: " + result.error().what());
  }

  return *result;
}

}  // namespace select_from_read_to_vector
```

