struct Operation {
  static constexpr Operator op = _op;

  using Operand1Type = _Operand1Type;
  using Operand2Type = _Operand2Type;
  using Operand3Type = _Operand3Type;

  Operand1Type operand1;
  Operand2Type operand2;
  Operand3Type operand3;

