```cpp
#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/select_from.hpp>
#include <sqlgen/joins.hpp>
#include <sqlgen/literals.hpp>
#include <sqlgen/to.hpp>
#include <rfl.hpp>

namespace analyze_department_employees {

struct Department {
  PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = *conn_result;

  // Create temporary tables
  conn.execute(R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS Department (
      department_id INTEGER PRIMARY KEY,
      department_name TEXT NOT NULL,
      location TEXT
    )
  )").or_else([](auto error) {
    throw std::runtime_error("Failed to create Department table: " + error.what());
  });

  conn.execute(R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS Employee (
      employee_id INTEGER PRIMARY KEY,
      department_id INTEGER,
      first_name TEXT NOT NULL,
      last_name TEXT NOT NULL,
      salary REAL NOT NULL,
      FOREIGN KEY (department_id) REFERENCES Department(department_id)
    )
  )").or_else([](auto error) {
    throw std::runtime_error("Failed to create Employee table: " + error.what());
  });

  // Clear existing data
  conn.execute("DELETE FROM Department").or_else([](auto error) {
    throw std::runtime_error("Failed to clear Department table: " + error.what());
  });

  conn.execute("DELETE FROM Employee").or_else([](auto error) {
    throw std::runtime_error("Failed to clear Employee table: " + error.what());
  });

  // Insert department data
  for (const auto& dept : depts) {
    conn.execute("INSERT INTO Department (department_id, department_name, location) VALUES (?, ?, ?)",
                dept.department_id.value, dept.department_name, dept.location)
        .or_else([](auto error) {
          throw std::runtime_error("Failed to insert department: " + error.what());
        });
  }

  // Insert employee data
  for (const auto& emp : emps) {
    conn.execute("INSERT INTO Employee (employee_id, department_id, first_name, last_name, salary) VALUES (?, ?, ?, ?, ?)",
                emp.employee_id.value, emp.department_id, emp.first_name, emp.last_name, emp.salary)
        .or_else([](auto error) {
          throw std::runtime_error("Failed to insert employee: " + error.what());
        });
  }

  JoinAnalysis analysis;

  // 1. INNER JOIN: Employees with assigned departments
  auto inner_join_query = sqlgen::select_from<Department>("d"_t1, 
        "department_name"_t1, "first_name"_t2, "last_name"_t2, "salary"_t2)
      | sqlgen::inner_join<Employee>("e"_t2, "department_id"_t1 == "department_id"_t2);

  auto inner_result = inner_join_query(conn).to<std::vector<JoinResult>>();
  if (inner_result) {
    analysis.inner_join_results = std::move(*inner_result);
  }

  // 2. LEFT JOIN: All employees (even without departments)
  auto left_join_query = sqlgen::select_from<Employee>("e"_t1,
        "department_name"_t2, "first_name"_t1, "last_name"_t1, "salary"_t1)
      | sqlgen::left_join<Department>("d"_t2, "department_id"_t1 == "department_id"_t2);

  auto left_result = left_join_query(conn).to<std::vector<JoinResult>>();
  if (left_result) {
    analysis.left_join_results = std::move(*left_result);
  }

  // 3. RIGHT JOIN: All departments (even without employees)
  // Note: SQLite doesn't natively support RIGHT JOIN, so we simulate it with LEFT JOIN
  auto right_join_query = sqlgen::select_from<Department>("d"_t1,
        "department_name"_t1, "first_name"_t2, "last_name"_t2, "salary"_t2)
      | sqlgen::left_join<Employee>("e"_t2, "department_id"_t1 == "department_id"_t2);

  auto right_result = right_join_query(conn).to<std::vector<JoinResult>>();
  if (right_result) {
    analysis.right_join_results = std::move(*right_result);
  }

  // 4. FULL JOIN: All employees and all departments
  // Note: SQLite doesn't natively support FULL JOIN, so we simulate it with UNION of LEFT and RIGHT joins
  auto full_join_query_part1 = sqlgen::select_from<Employee>("e"_t1,
        "department_name"_t2, "first_name"_t1, "last_name"_t1, "salary"_t1)
      | sqlgen::left_join<Department>("d"_t2, "department_id"_t1 == "department_id"_t2);

  auto full_join_query_part2 = sqlgen::select_from<Department>("d"_t1,
        "department_name"_t1, "first_name"_t2, "last_name"_t2, "salary"_t2)
      | sqlgen::left_join<Employee>("e"_t2, "department_id"_t1 == "department_id"_t2)
      | sqlgen::where("employee_id"_t2.is_null());

  // For FULL JOIN simulation, we need to use raw SQL since the library might not support UNION directly
  auto full_result = conn.read<JoinResult>(R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Employee e
    LEFT JOIN Department d ON e.department_id = d.department_id
    UNION
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Department d
    LEFT JOIN Employee e ON d.department_id = e.department_id
    WHERE e.employee_id IS NULL
  )");

  if (full_result) {
    analysis.full_join_results = std::move(*full_result);
  }

  return analysis;
}

}  // namespace analyze_department_employees
