struct ToTranspilationType<sqlgen::Col<_name, _alias>> {
  using Type = transpilation::Col<_name, _alias>;

  Type operator()(const auto&) const noexcept {
    return transpilation::Col<_name, _alias>{};
  }
};
}  // namespace transpilation

