#include "sqlgen/select_from.hpp"
#include "sqlgen/mysql/to_sql.hpp"
#include "sqlgen/literals.hpp"

namespace aggregation_arithmetic {

struct Product {
  PrimaryKey<int> id;
  double price;
};

/**
 * This function demonstrates arithmetic on aggregations.
 * Returns: std::string.
 */
inline std::string aggregation_arithmetic() {
    using namespace sqlgen::literals;

    // Construct the query: SELECT AVG(price) + 10.0 FROM Product
    auto query = sqlgen::select_from<Product>(sqlgen::avg("price"_c) + 10.0);

    // Generate and return the SQL string
    return sqlgen::mysql::to_sql(query);
}

}  // namespace aggregation_arithmetic
